// Turn the caller's list into one item per term, and note which ones already look like a ticker.
// Only text typed in capitals counts as a ticker (TSLA, MC.PA): "ford" means Ford Motor, not the FORD ticker.
const TICKER = /^[A-Z0-9^][A-Z0-9.=^-]{0,11}$/;
let raw = $input.first().json.terms;
if (typeof raw === 'string') { try { raw = JSON.parse(raw); } catch (e) { raw = raw.split(','); } }
if (!Array.isArray(raw)) raw = [];
const seen = new Set();
const out = [];
for (const t of raw) {
  const term = String(t === null || t === undefined ? '' : t).replace(/\s+/g, ' ').trim().slice(0, 60);
  const key = term.toLowerCase();
  if (!term || seen.has(key)) continue;
  seen.add(key);
  const candidate = term.replace(/^\$/, '');
  out.push({ json: { idx: out.length, term: term, candidate: candidate, ticker_shaped: TICKER.test(candidate) } });
  if (out.length >= 30) break;
}
return out;

// Every term has now been tried against Yahoo. Put them back in the order the person typed them,
// and list the ones Yahoo could not place: only those go to the AI, all together in one call.
const results = $input.all().map(i => i.json).filter(r => r && r.term).sort((a, b) => a.idx - b.idx);
const unresolved = results.filter(r => r.status === 'needs_ai').map(r => r.term);
return [{ json: { results: results, unresolved: unresolved, ai_needed: unresolved.length > 0 } }];

// The AI only suggests. Each suggestion must look like a ticker, and is then checked on Yahoo before it counts.
const TICKER = /^[A-Z0-9^][A-Z0-9.=^-]{0,11}$/;
const asked = $('Gather Lookup Results').first().json.unresolved;
const inp = $input.first().json || {};
let out = inp.output;
if (typeof out === 'string') { try { out = JSON.parse(out); } catch (e) { out = null; } }
const list = out && Array.isArray(out.suggestions) ? out.suggestions : [];
const checks = [];
asked.forEach((term, i) => {
  let s = list.find(x => x && String(x.term || '').trim().toLowerCase() === term.toLowerCase());
  if (!s && list.length === asked.length) s = list[i];
  const symbol = s ? String(s.symbol || '').trim().toUpperCase() : '';
  if (symbol && TICKER.test(symbol)) checks.push({ json: { none: false, term: term, symbol: symbol } });
});
if (!checks.length) return [{ json: { none: true } }];
return checks;

// Final answer, one item per term in the order typed: what it resolved to, how, and whether that worked.
// An AI suggestion only becomes "found" if Yahoo confirmed the ticker exists and has a price.
const base = $('Gather Lookup Results').first().json.results;
let checks = [];
let verified = [];
try {
  verified = $('Verify AI Ticker On Yahoo').all().map(i => i.json);
  checks = $('Plan AI Checks').all().map(i => i.json);
} catch (e) { verified = []; checks = []; }
const byTerm = {};
checks.forEach((c, i) => { if (!c.none) byTerm[c.term] = { symbol: c.symbol, res: verified[i] || {} }; });
return base.map(r => {
  const out = { term: r.term, symbol: r.symbol || '', name: r.name || '', method: r.method, status: r.status };
  if (r.status !== 'needs_ai') return { json: out };
  out.method = 'ai';
  out.status = 'not_found';
  const c = byTerm[r.term];
  if (!c) return { json: out };
  let body = c.res.body;
  if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = null; } }
  const chart = body && body.chart;
  const meta = chart && chart.result && chart.result[0] && chart.result[0].meta;
  if (c.res.statusCode === 200 && meta && typeof meta.regularMarketPrice === 'number') {
    out.status = 'found';
    out.symbol = String(meta.symbol || c.symbol).toUpperCase();
    out.name = meta.shortName || meta.longName || '';
  } else if (!(c.res.statusCode === 404 || c.res.statusCode === 200 || (chart && chart.error))) {
    out.status = 'lookup_unavailable';
  }
  return { json: out };
});

// 200 with a price = the ticker exists. 404 = no such ticker, so try it as a name instead.
// Anything else (timeout, 5xx, rate limit) is Yahoo's trouble, not the user's: the name search gets a go too.
const t = $('Looks Like A Ticker?').item.json;
const r = $json || {};
let body = r.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = null; } }
const chart = body && body.chart;
const meta = chart && chart.result && chart.result[0] && chart.result[0].meta;
if (r.statusCode === 200 && meta && typeof meta.regularMarketPrice === 'number') {
  return { json: { idx: t.idx, term: t.term, status: 'found', method: 'exact',
    symbol: String(meta.symbol || t.candidate).toUpperCase(), name: meta.shortName || meta.longName || '' } };
}
const exact = (r.statusCode === 404 || r.statusCode === 200 || (chart && chart.error)) ? 'missing' : 'unavailable';
return { json: Object.assign({}, t, { status: 'pending', exact: exact }) };

// Yahoo's own search turns a name into a ticker. Futures and options are skipped (an "airbus" future is not a stock);
// shares come first, then funds, then indices. An empty search is left for the AI step.
const t = $('Looks Like A Ticker?').item.json;
const r = $json || {};
let body = r.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = null; } }
const base = { idx: t.idx, term: t.term, method: 'search', symbol: '', name: '' };
if (r.statusCode !== 200 || !body || typeof body !== 'object') {
  return { json: Object.assign(base, { status: 'lookup_unavailable' }) };
}
const RANK = { EQUITY: 0, ETF: 1, INDEX: 2 };
const quotes = (Array.isArray(body.quotes) ? body.quotes : [])
  .filter(q => q && q.symbol && q.quoteType !== 'FUTURE' && q.quoteType !== 'OPTION');
const rank = q => (q.quoteType in RANK ? RANK[q.quoteType] : 3);
const best = quotes.slice().sort((a, b) => rank(a) - rank(b))[0];
if (!best) return { json: Object.assign(base, { status: 'needs_ai' }) };
return { json: Object.assign(base, { status: 'found', symbol: String(best.symbol).toUpperCase(),
  name: best.shortname || best.longname || '' }) };
